<?php
declare(strict_types=1);
namespace SimpleMSPDoc\Tests\Integration;
final class HttpAcceptanceTest extends DatabaseTestCase
{
 private $server;
 private string $base;
 private string $cookie;
 private string $prefix='';
 private function startServer(string $prefix='',?string $packagedRoot=null): void {
  $this->prefix=$prefix;$port=random_int(21000,29000);$this->base='http://127.0.0.1:'.$port.$prefix;$this->cookie=$this->root.'/cookies';
  $env=array_merge(getenv(),['SIMPLEMSPDOC_PRIVATE_ROOT'=>$packagedRoot??$this->root,'SIMPLEMSPDOC_BASE_PATH'=>$prefix]);
  $docroot=$this->root.'/web';mkdir($docroot,0700,true);$site=$docroot.$prefix;if($prefix!=='')mkdir($site,0700,true);file_put_contents($site.'/index.php','<?php require '.var_export(dirname(__DIR__,2).'/index.php',true).';');symlink(dirname(__DIR__,2).'/assets',$site.'/assets');symlink($this->root.'/data',$site.'/data');if($packagedRoot!==null)$docroot=$packagedRoot;$this->server=proc_open([PHP_BINARY,'-c',php_ini_loaded_file(),'-S','127.0.0.1:'.$port,'-t',$docroot],[0=>['pipe','r'],1=>['file',$this->root.'/server.log','a'],2=>['file',$this->root.'/server.log','a']],$pipes,dirname(__DIR__,2),$env);

  for($i=0;$i<100;$i++){try{$r=$this->request('GET','/login');if($r['status']>0)return;}catch(\Throwable){}usleep(20000);}throw new \RuntimeException('HTTP server did not start: '.file_get_contents($this->root.'/server.log'));
 }
 protected function tearDown(): void {if(is_resource($this->server)){proc_terminate($this->server);proc_close($this->server);}foreach(glob($this->root.'/data/*.log.php') as $log)file_put_contents(dirname(__DIR__,2).'/.superpowers/http-debug.log',file_get_contents($log),FILE_APPEND);file_put_contents(dirname(__DIR__,2).'/.superpowers/http-debug.log',file_get_contents($this->root.'/server.log'),FILE_APPEND);parent::tearDown();}
 private function entryPath(string $path): string {if(str_starts_with($path,'/assets/')||str_starts_with($path,'/data/')||str_starts_with($path,'/index.php')||$path==='/')return $path;$parts=explode('?',$path,2);$query='route='.rawurlencode($parts[0]);if(isset($parts[1]))$query.='&'.$parts[1];return '/index.php?'.$query;}
 private function request(string $method,string $path,array $data=[]): array {
  $c=curl_init($this->base.$this->entryPath($path));curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$this->cookie,CURLOPT_COOKIEFILE=>$this->cookie,CURLOPT_TIMEOUT=>5]);if($method==='POST'){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($data));}
  $raw=curl_exec($c);if($raw===false)throw new \RuntimeException(curl_error($c));$size=curl_getinfo($c,CURLINFO_HEADER_SIZE);$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);unset($c);clearstatcache();return ['status'=>$status,'body'=>substr($raw,$size),'headers'=>substr($raw,0,$size)];
 }
 private function csrf(string $path): string {$r=$this->request('GET',$path);preg_match('/name="_csrf" value="([a-f0-9]+)"/',$r['body'],$m);self::assertNotEmpty($m,'CSRF token missing from '.$path.' status '.$r['status'].' '.$r['body']);return $m[1];}
 private function installed(): int {$this->schema();$id=$this->user();$this->db->run("UPDATE users SET username='admin' WHERE id=?",[$id]);file_put_contents($this->root.'/data/config.php','<?php return '.var_export(['database'=>['dsn'=>getenv('TEST_DSN'),'username'=>getenv('TEST_DB_USER')?:'root','password'=>getenv('TEST_DB_PASSWORD')?:''],'key'=>base64_encode(random_bytes(32)),'upload_limit'=>20971520],true).';');return $id;}
 private function login(): void {$token=$this->csrf('/login');$r=$this->request('POST','/login',['_csrf'=>$token,'username'=>'admin','password'=>'Correct-password-123']);self::assertSame(303,$r['status'],$r['body']);}
 public function testWebInstallerLocksAndSubpathAssetsLoad(): void {
  $this->startServer('/docs');$first=$this->request('GET','/');self::assertSame(303,$first['status']);self::assertStringContainsString('/docs/index.php?route=%2Finstall',$first['headers']);$r=$this->request('GET','/install');self::assertSame(200,$r['status']);self::assertStringContainsString('Fresh installation',$r['body']);self::assertStringNotContainsString('name="setup_token"',$r['body']);self::assertStringContainsString('name="database_host"',$r['body']);self::assertStringNotContainsString('setup.key',$r['body']);
  $r=$this->request('POST','/install',['_csrf'=>$this->csrf('/install'),'dsn'=>getenv('TEST_DSN'),'database_user'=>getenv('TEST_DB_USER')?:'root','database_password'=>getenv('TEST_DB_PASSWORD')?:'','username'=>'admin','name'=>'Admin','password'=>'Correct-password-123']);self::assertSame(303,$r['status'],$r['body']);
  $this->login();self::assertSame(403,$this->request('GET','/install')['status']);self::assertSame(404,$this->request('GET','/data/config.php')['status']);$r=$this->request('GET','/');self::assertSame(200,$r['status']);self::assertStringContainsString('/docs/assets/app.css',$r['body']);self::assertStringContainsString('name="route" value="/search"',$r['body']);self::assertSame(200,$this->request('GET','/assets/app.css')['status']);
 }
 public function testSharedTemplatesAndOrganizationNavigation(): void {
  $this->installed();$this->startServer();$this->login();foreach($this->db->all('SELECT id,name FROM asset_types') as $t){$r=$this->request('GET','/templates/'.$t['id']);self::assertSame(200,$r['status']);self::assertStringContainsString($t['name'],$r['body']);}
  $org=$this->org();foreach(['/organizations/'.$org,'/organizations/'.$org.'/asset','/organizations/'.$org.'/contact','/organizations/'.$org.'/article','/organizations/'.$org.'/location','/organizations/'.$org.'/passwords'] as $path){$r=$this->request('GET',$path);self::assertSame(200,$r['status']);foreach(['Configurations','Contacts','Documents','Locations','Passwords'] as $label)self::assertStringContainsString($label,$r['body']);}
 }
 public function testInvalidLogoRollsBackAndValidLogoRequiresOrganizationAccess(): void {
  $this->installed();$this->startServer();$this->login();$tmp=$this->root.'/logo.png';file_put_contents($tmp,'<svg onload="alert(1)"></svg>');$send=function()use($tmp){$c=curl_init($this->base.$this->entryPath('/organizations/save'));curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>['_csrf'=>$this->csrf('/organizations/new'),'name'=>'Logo customer','logo'=>new \CURLFile($tmp,'image/png','logo.png')],CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>$this->cookie]);$body=curl_exec($c);$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return [$status,$body];};self::assertSame(422,$send()[0]);self::assertSame([],$this->db->all('SELECT id FROM organizations'));file_put_contents($tmp,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jK1kAAAAASUVORK5CYII='));self::assertSame(303,$send()[0]);$org=(int)$this->db->one('SELECT id FROM organizations')['id'];$r=$this->request('GET',"/organizations/$org/logo");self::assertSame(200,$r['status']);self::assertSame(file_get_contents($tmp),$r['body']);self::assertStringContainsString('image/png',$r['headers']);$this->request('POST','/logout',['_csrf'=>$this->csrf('/')]);self::assertSame(303,$this->request('GET',"/organizations/$org/logo")['status']);
 }
 public function testPasswordFormsRevealEditAndConfigurationLink(): void {
  $this->installed();$this->startServer();$this->login();$org=$this->org();$asset=(new \SimpleMSPDoc\Modules\Assets\AssetService($this->db,new \SimpleMSPDoc\Modules\Audit\AuditService($this->db)))->create(new \SimpleMSPDoc\Core\Actor((int)$this->db->one("SELECT id FROM users WHERE username='admin'")['id'],'administrator','staff'),$org,['title'=>'DC01','payload'=>['template_id'=>1,'values'=>[]]]);
  $r=$this->request('POST',"/organizations/$org/passwords/save",['_csrf'=>$this->csrf("/organizations/$org/passwords/new"),'title'=>'Local admin','username'=>'root','secret'=>'Secret<&123','configuration_id'=>$asset]);self::assertSame(303,$r['status'],$r['body']);$id=(int)$this->db->one('SELECT id FROM passwords')['id'];$r=$this->request('GET',"/passwords/$id");self::assertSame(200,$r['status']);self::assertStringNotContainsString('Secret',$r['body']);self::assertStringContainsString('DC01',$r['body']);self::assertStringContainsString('Local admin',$this->request('GET',"/records/$asset")['body']);
  self::assertSame(403,$this->request('POST',"/passwords/$id/reveal",[])['status']);$r=$this->request('POST',"/passwords/$id/reveal",['_csrf'=>$this->csrf("/passwords/$id")]);self::assertSame(200,$r['status']);self::assertStringContainsString('Secret&lt;&amp;123',$r['body']);self::assertStringContainsString('Cache-Control: no-store',$r['headers']);self::assertStringNotContainsString('Secret',$this->request('GET',"/passwords/$id/edit")['body']);
  $r=$this->request('POST',"/passwords/$id/save",['_csrf'=>$this->csrf("/passwords/$id/edit"),'title'=>'Updated admin','username'=>'root','secret'=>'','configuration_id'=>$asset,'revision'=>1]);self::assertSame(303,$r['status']);self::assertStringContainsString('Secret&lt;&amp;123',$this->request('POST',"/passwords/$id/reveal",['_csrf'=>$this->csrf("/passwords/$id")])['body']);
 }
 public function testInstalledAlpha3UpgradesWithoutLosingOrganization(): void {
  foreach(require dirname(__DIR__,2).'/database/migrations/001_initial.php' as $sql)$this->db->run($sql);$id=$this->user();$this->db->run("UPDATE users SET username='admin' WHERE id=?",[$id]);$org=$this->org('Existing customer');file_put_contents($this->root.'/data/config.php','<?php return '.var_export(['database'=>['dsn'=>getenv('TEST_DSN'),'username'=>getenv('TEST_DB_USER')?:'root','password'=>getenv('TEST_DB_PASSWORD')?:''],'key'=>base64_encode(random_bytes(32))],true).';');$this->startServer();$this->login();self::assertSame(303,$this->request('GET',"/organizations/$org")['status']);$r=$this->request('GET','/upgrade');self::assertSame(200,$r['status']);self::assertStringContainsString('002_organization_passwords',$r['body']);$r=$this->request('POST','/upgrade',['_csrf'=>$this->csrf('/upgrade'),'backup'=>1]);self::assertContains($r['status'],[200,303]);self::assertSame(200,$this->request('GET',"/organizations/$org")['status']);self::assertSame('Existing customer',$this->db->one('SELECT name FROM organizations WHERE id=?',[$org])['name']);
 }
 public function testRealFormsCreateDocumentationAndRejectClientAccess(): void {
  $this->installed();$this->startServer();$this->login();$r=$this->request('POST','/organizations/save',['_csrf'=>$this->csrf('/organizations/new'),'name'=>'Example Customer','description'=>'IT documentation']);self::assertSame(303,$r['status'],$r['body']);$org=(int)$this->db->one('SELECT id FROM organizations')['id'];
  $r=$this->request('POST',"/organizations/$org/article/save",['_csrf'=>$this->csrf("/organizations/$org/article/new"),'title'=>'Recovery instructions','visibility'=>'internal','html'=>'<p>Restore from backup</p>','category'=>'Operations','tags'=>'recovery']);self::assertSame(303,$r['status'],$r['body']);$id=(int)$this->db->one('SELECT id FROM records')['id'];self::assertStringContainsString('Restore from backup',$this->request('GET',"/records/$id")['body']);
  $r=$this->request('POST',"/records/$id/save",['_csrf'=>$this->csrf("/records/$id/edit"),'title'=>'Recovery instructions v2','visibility'=>'internal','html'=>'<p>Updated</p>','revision'=>1]);self::assertSame(303,$r['status'],$r['body']);self::assertSame(409,$this->request('POST',"/records/$id/save",['_csrf'=>$this->csrf("/records/$id/edit"),'title'=>'stale','visibility'=>'internal','html'=>'stale','revision'=>1])['status']);
  self::assertStringContainsString('Recovery instructions v2',$this->request('GET','/search?q=Recovery')['body']);self::assertSame(403,$this->request('POST','/organizations/save',['name'=>'No CSRF'])['status']);
  $client=$this->user('read-only','client');$this->db->run("UPDATE users SET username='client' WHERE id=?",[$client]);$this->db->run('INSERT INTO user_organizations VALUES (?,?)',[$client,$org]);$this->request('POST','/logout',['_csrf'=>$this->csrf('/')]);$r=$this->request('POST','/login',['_csrf'=>$this->csrf('/login'),'username'=>'client','password'=>'Correct-password-123']);self::assertSame(303,$r['status']);self::assertSame(404,$this->request('GET',"/records/$id")['status']);self::assertSame(403,$this->request('GET','/users')['status']);self::assertStringNotContainsString('Recovery instructions',$this->request('GET','/search?q=Recovery')['body']);
 }
 public function testRequiredMfaDoesNotGrantSessionBeforeEnrollment(): void {
  $id=$this->installed();$this->db->run('UPDATE users SET require_mfa=1 WHERE id=?',[$id]);$this->startServer();$this->login();self::assertSame(303,$this->request('GET','/users')['status']);$r=$this->request('GET','/mfa/enroll');self::assertStringContainsString('Authenticator setup',$r['body']);self::assertSame(200,$r['status']);
 }
 public function testAssetFormsRelationshipsUploadsAndRevisionRestore(): void {
  $this->installed();$this->startServer();$this->login();$org=$this->org();$other=$this->org('Another organization');
  $r=$this->request('POST',"/organizations/$org/location/save",['_csrf'=>$this->csrf("/organizations/$org/location/new"),'title'=>'Main office','visibility'=>'internal','address'=>'123 Main Street']);self::assertSame(303,$r['status'],$r['body']);$location=(int)$this->db->one("SELECT id FROM records WHERE type='location'")['id'];
  $type=(int)$this->db->one("SELECT id FROM asset_types WHERE name='Server'")['id'];$field=(int)$this->db->one('SELECT id FROM asset_fields WHERE asset_type_id=? ORDER BY id LIMIT 1',[$type])['id'];
  $r=$this->request('POST',"/organizations/$org/asset/save",['_csrf'=>$this->csrf("/organizations/$org/asset/new?template=$type"),'title'=>'DC01','template_id'=>$type,'values'=>[$field=>'dc01.example.test'],'location_id'=>$location,'visibility'=>'client']);self::assertSame(303,$r['status'],$r['body']);$asset=(int)$this->db->one("SELECT id FROM records WHERE type='asset'")['id'];$body=$this->request('GET',"/records/$asset")['body'];self::assertStringContainsString('dc01.example.test',$body);self::assertStringContainsString('Main office',$body);
  $r=$this->request('POST',"/records/$asset/relationships",['_csrf'=>$this->csrf("/records/$asset"),'target_id'=>$location]);self::assertSame(303,$r['status'],$r['body']);
  $tmp=$this->root.'/notes.txt';file_put_contents($tmp,'Asset notes');$curl=curl_init($this->base.$this->entryPath("/records/$asset/attachments"));curl_setopt_array($curl,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>['_csrf'=>$this->csrf("/records/$asset"),'attachment'=>new \CURLFile($tmp,'text/plain','notes.txt')],CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>$this->cookie]);$body=curl_exec($curl);self::assertSame(303,curl_getinfo($curl,CURLINFO_RESPONSE_CODE),$body);unset($curl);$attachment=(int)$this->db->one('SELECT id FROM attachments')['id'];self::assertSame('Asset notes',$this->request('GET',"/attachments/$attachment")['body']);$storage=$this->db->one('SELECT storage_name FROM attachments WHERE id=?',[$attachment])['storage_name'];self::assertSame(404,$this->request('GET','/data/uploads/'.$storage)['status']);
  foreach([['First','<p>First text</p>'],['Second','<p>Second text</p>']] as $i=>[$title,$html]){if($i===0){$path="/organizations/$org/article/save";$form="/organizations/$org/article/new";}else{$article=(int)$this->db->one("SELECT id FROM records WHERE type='article'")['id'];$path="/records/$article/save";$form="/records/$article/edit";}$r=$this->request('POST',$path,['_csrf'=>$this->csrf($form),'title'=>$title,'html'=>$html,'revision'=>1]);self::assertSame(303,$r['status'],$r['body']);}
  $revision=(int)$this->db->one('SELECT id FROM revisions ORDER BY id LIMIT 1')['id'];$r=$this->request('POST',"/records/$article/revisions/$revision/restore",['_csrf'=>$this->csrf("/records/$article/revisions/$revision"),'expected_revision'=>2]);self::assertSame(303,$r['status'],$r['body']);self::assertSame('First',$this->db->one('SELECT title FROM records WHERE id=?',[$article])['title']);
  $client=$this->user('read-only','client');$this->db->run("UPDATE users SET username='client' WHERE id=?",[$client]);$this->db->run('INSERT INTO user_organizations VALUES (?,?)',[$client,$org]);$this->request('POST','/logout',['_csrf'=>$this->csrf('/')]);$this->request('POST','/login',['_csrf'=>$this->csrf('/login'),'username'=>'client','password'=>'Correct-password-123']);$body=$this->request('GET',"/records/$asset")['body'];self::assertStringContainsString('DC01',$body);self::assertStringNotContainsString('Main office',$body);self::assertStringNotContainsString('Another organization',$body);self::assertSame('Asset notes',$this->request('GET',"/attachments/$attachment")['body']);$storage=$this->db->one('SELECT storage_name FROM attachments WHERE id=?',[$attachment])['storage_name'];self::assertSame(404,$this->request('GET','/data/uploads/'.$storage)['status']);self::assertSame(403,$this->request('GET',"/records/$asset/edit")['status']);
 }

 public function testInstallerFormNeedsNoOwnershipVerificationAndRejectsMissingCsrf(): void {
  $this->startServer();$body=$this->request('GET','/install')['body'];self::assertStringContainsString('name="database_host"',$body);self::assertStringNotContainsString('setup.key',$body);self::assertStringNotContainsString('Verify that you manage',$body);self::assertSame(403,$this->request('POST','/install',[])['status']);self::assertSame([],$this->db->all('SHOW TABLES'));
 }

 public function testActualFlatReleaseInstallsWithNoRouter(): void {
  $archive=$this->root.'/package.zip';(new \SimpleMSPDoc\Core\ReleaseBuilder(dirname(__DIR__,2)))->build('2.0.0-alpha.4',$archive);$site=$this->root.'/site';mkdir($site);$zip=new \ZipArchive();self::assertTrue($zip->open($archive));self::assertTrue($zip->extractTo($site));$zip->close();self::assertFileExists($site.'/index.php');self::assertDirectoryDoesNotExist($site.'/public');
  $this->startServer('', $site);$r=$this->request('GET','/');self::assertSame(303,$r['status']);self::assertStringContainsString('/index.php?route=%2Finstall',$r['headers']);$r=$this->request('POST','/install',['_csrf'=>$this->csrf('/install'),'dsn'=>getenv('TEST_DSN'),'database_user'=>getenv('TEST_DB_USER')?:'root','database_password'=>getenv('TEST_DB_PASSWORD')?:'','username'=>'admin','name'=>'Admin','password'=>'Correct-password-123']);self::assertSame(303,$r['status'],$r['body']);$this->login();self::assertSame(200,$this->request('GET','/')['status']);self::assertSame(404,$this->request('GET','/data/config.php')['status']);$session=basename(glob($site.'/data/sessions/*.php')[0]);self::assertSame(404,$this->request('GET','/data/sessions/'.$session)['status']);self::assertSame(200,$this->request('GET','/assets/app.css')['status']);
 }

